[{"order":1,"type":"heading","text":"Mastering Mutation Patterns, Optimistic Updates, and useOptimistic in Next.js"},{"order":2,"type":"paragraph","text":"Building high-performance web applications requires instant feedback when users interact with the UI. In Next.js, combining Server Actions with React's useOptimistic hook allows developers to implement optimistic updates seamlessly, bridging the gap between server-side mutations and client-side responsiveness."},{"order":3,"type":"subheading","text":"Understanding Mutation Patterns in Next.js"},{"order":4,"type":"paragraph","text":"Traditional data mutations involve triggering an API request, waiting for the server to process the change, and then revalidating or updating the local state. While safe, this pattern can feel sluggish because the UI remains unresponsive during the network round-trip."},{"order":5,"type":"bullet_point","text":"Standard Mutation: User action -> Server Request -> Database Update -> Response -> UI Refresh."},{"order":6,"type":"bullet_point","text":"Optimistic Mutation: User action -> Immediate UI Update -> Background Server Request -> Sync/Revert if error."},{"order":7,"type":"subheading","text":"Introduction to useOptimistic"},{"order":8,"type":"paragraph","text":"React 19 introduces the useOptimistic hook, which lets you optimistically update the UI before a asynchronous action finishes. It accepts a current state and an update function that calculates the optimistic state based on the current state and the incoming mutation."},{"order":9,"type":"subheading","text":"Implementing an Optimistic Todo List"},{"order":10,"type":"paragraph","text":"Below is a practical implementation of a Next.js Client Component utilizing useOptimistic alongside a Server Action to manage a list of todos instantly."},{"order":11,"type":"code","text":""use client";

import { useOptimistic, useRef } from "react";
import { addTodo } from "@/app/actions";

export default function TodoList({ initialTodos }) {
  const formRef = useRef(null);
  const [optimisticTodos, setOptimisticTodos] = useOptimistic(
    initialTodos,
    (state, newTodo) => [...state, { text: newTodo, pending: true }]
  );

  async function handleSubmit(formData) {
    const text = formData.get("todo");
    formRef.current?.reset();
    setOptimisticTodos(text);
    await addTodo(text);
  }

  return (
    <div className="p-4">
      <form ref={formRef} action={handleSubmit}>
        <input type="text" name="todo" placeholder="Add a new todo..." required className="border p-2 mr-2" />
        <button type="submit" className="bg-blue-500 text-white p-2">Add</button>
      </form>
      <ul className="mt-4">
        {optimisticTodos.map((todo, index) => (
          <li key={index} style={{ opacity: todo.pending ? 0.5 : 1 }}>
            {todo.text} {todo.pending && "(Saving...)"}
          </li>
        ))}
      </ul>
    </div>
  );
}"},{"order":12,"type":"subheading","text":"Best Practices for Error Handling and Revalidation"},{"order":13,"type":"paragraph","text":"Optimistic updates assume success. However, network failures or server validation errors can occur. Always ensure your Server Actions call revalidatePath to sync the actual database state, and design your UI to gracefully revert if the mutation throws an exception."}]
